"""Master list of CSE 211 TF questions -> questions.json.
Row: (year, qno, marks, page, teacher, lesson, type, key, text)
teacher H = Hakim, A = Atif, O = outside (Atif-side, not in slides).
Lesson numbers: Hakim L1-L24, Atif L1-L26 (see PROGRESS.md plan).
page = page in 'CSE 211 All Merged Questions.pdf', or '22 batch p.N'.
"""
import json, os

Q = []


def P(year, rows):
    for r in rows:
        Q.append(dict(year=year, qno=r[0], marks=r[1], page=r[2], teacher=r[3], lesson=r[4],
                      type=r[5], key=r[6], question=r[7]))


